CREATE FUNCTION private.protect_tariff_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.recurring_expense_id IS DISTINCT FROM OLD.recurring_expense_id THEN RAISE EXCEPTION 'Fixkosten-Verknüpfungen sind unveränderlich.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER transactions_tariff_links BEFORE UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION private.protect_tariff_links();
CREATE FUNCTION private.validate_subscription_state() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.plan_id='free' AND NEW.status IN ('active','trialing','past_due','canceled') THEN RAISE EXCEPTION 'Free benötigt den kostenlosen Status.'; END IF; IF NEW.status='free' AND NEW.plan_id<>'free' THEN RAISE EXCEPTION 'Kostenloser Status benötigt Free.'; END IF; IF NEW.status IN ('active','trialing','past_due','canceled') AND NEW.period_end IS NULL THEN RAISE EXCEPTION 'Tarifende erforderlich.'; END IF; IF TG_OP='UPDATE' AND NEW.status='trialing' AND OLD.status<>'trialing' AND OLD.trial_used THEN RAISE EXCEPTION 'Die einmalige Testphase wurde bereits genutzt.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER subscription_state BEFORE INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION private.validate_subscription_state();
CREATE FUNCTION public.operator_refund_ocr(_request uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old ocr_usage%ROWTYPE; BEGIN IF NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Nur für den autorisierten Betreiber.'; END IF; IF length(btrim(coalesce(_reason,'')))<10 THEN RAISE EXCEPTION 'Prüfergebnis und Erstattungsgrund angeben (mindestens 10 Zeichen).'; END IF; SELECT * INTO old FROM ocr_usage WHERE id=_request FOR UPDATE; IF old.state IS DISTINCT FROM 'reserved' THEN RAISE EXCEPTION 'Nur ungeklärte Reservierungen können nach Prüfung erstattet werden.'; END IF; UPDATE ocr_usage SET state='refunded',reason=_reason,updated_at=now() WHERE id=_request; INSERT INTO subscription_audit(organization_id,administrator,reason,before_value,after_value) VALUES(old.organization_id,auth.uid(),_reason,to_jsonb(old),jsonb_build_object('request',_request,'state','refunded')); END $$;
REVOKE ALL ON FUNCTION public.operator_refund_ocr(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.operator_refund_ocr(uuid,text) TO authenticated;
CREATE FUNCTION public.operator_ocr_reservations() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.is_platform_operator() THEN RAISE EXCEPTION 'Nur für den autorisierten Betreiber.'; END IF; RETURN (SELECT coalesce(jsonb_agg(r),'[]') FROM (SELECT id,organization_id,state,created_at,reason FROM ocr_usage WHERE state='reserved' ORDER BY created_at LIMIT 100) r); END $$;
REVOKE ALL ON FUNCTION public.operator_ocr_reservations() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.operator_ocr_reservations() TO authenticated;